+    alignas(64) uint32_t sub[NSUB][256];
+    for (int j = 0; j < NSUB; ++j)
+        for (int b = 0; b < 256; ++b) sub[j][b] = 0;
+
+    size_t i = 0;
+    int64_t off = 0;
+    // 4-wide blocks: whole block routed to sub[(i>>2)&7], so the four low-byte
