+        out[i] = s0; out[i + 1] = s1; out[i + 2] = s2; out[i + 3] = s3;
+        off = s3;
+        uint32_t* h = sub[(i >> 2) & (NSUB - 1)];
+        h[v0 & 255]++;
+        h[v1 & 255]++;
+        h[v2 & 255]++;
+        h[v3 & 255]++;
+    }
+    for (; i < n; ++i) {
+        int64_t v = in[i];
+        int64_t s = off + v;
+        out[i] = s;
